import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.data.redis.core.SetOperations;

import com.sky.dto.DishDTO;
import com.sky.dto.DishPageQueryDTO;
import com.sky.entity.Dish;
import com.sky.result.PageResult;
import com.sky.result.Result;
import com.sky.service.DishService;
import com.sky.vo.DishVO;

@ExtendWith(MockitoExtension.class)
class DishControllerTest {

    @InjectMocks
    private DishController dishController;

    @Mock
    private DishService dishService;

    @Mock
    private RedisTemplate<String, Object> redisTemplate;

    @Test
    @DisplayName("正向测试：验证启用或停用菜品方法正常工作")
    void startOrStop_withValidStatusAndId_shouldCallService() {
        // Arrange
        Integer status = 1;
        Long id = 100L;
        SetOperations<String, Object> setOperations = mock(SetOperations.class);
        when(redisTemplate.keys(anyString())).thenReturn(new HashSet<>(Arrays.asList("key1", "key2")));
        when(redisTemplate.delete(any(Set.class))).thenReturn(2L);

        // Act
        Result<String> result = dishController.startOrStop(status, id);

        // Assert
        assertNotNull(result);
        assertEquals("success", result.getData());
        verify(dishService).startOrStop(status, id);
    }

    @Test
    @DisplayName("边界测试：验证修复后路径变量正确绑定，不再抛出异常")
    void startOrStop_withPathVariable_shouldNotThrowMissingPathVariableException() {
        // Arrange
        Integer status = 0;
        Long id = 200L;
        when(redisTemplate.keys(anyString())).thenReturn(Collections.emptySet());

        // Act & Assert - 这里主要验证方法调用不会抛出异常
        assertDoesNotThrow(() -> dishController.startOrStop(status, id));
        verify(dishService).startOrStop(status, id);
    }

    @Test
    @DisplayName("正向测试：验证保存菜品方法正常工作")
    void save_withValidDishDTO_shouldCallService() {
        // Arrange
        DishDTO dishDTO = new DishDTO();
        dishDTO.setCategoryId(1L);
        when(redisTemplate.keys(anyString())).thenReturn(Collections.emptySet());

        // Act
        Result<String> result = dishController.save(dishDTO);

        // Assert
        assertNotNull(result);
        assertEquals("success", result.getData());
        verify(dishService).saveWithFlavor(dishDTO);
    }

    @Test
    @DisplayName("正向测试：验证分页查询方法正常工作")
    void page_withValidQueryDTO_shouldReturnPageResult() {
        // Arrange
        DishPageQueryDTO queryDTO = new DishPageQueryDTO();
        PageResult<DishVO> pageResult = new PageResult<>(10L, Arrays.asList(new DishVO()));
